export async function processAll(items: string[]): Promise<Report> {
  // Step 1: validate all inputs
  const valid: string[] = [];
  const invalid: string[] = [];
  for (const item of items) {
    if (item && item.length > 0 && item.length <= 100) {
      valid.push(item);
    } else {
      invalid.push(item);
    }
  }

  // Step 2: transform valid items
  const transformed: TransformedItem[] = [];
  for (const item of valid) {
    const upper = item.toUpperCase();
    const reversed = item.split('').reverse().join('');
    transformed.push({ original: item, upper, reversed, length: item.length });
  }

  // Step 3: aggregate statistics
  let totalLength = 0;
  let minLength = Infinity;
  let maxLength = 0;
  for (const t of transformed) {
    totalLength += t.length;
    if (t.length < minLength) minLength = t.length;
    if (t.length > maxLength) maxLength = t.length;
  }
  if (transformed.length === 0) minLength = 0;

  // Step 4: format report
  const report: Report = {
    totalItems: items.length,
    validCount: valid.length,
    invalidCount: invalid.length,
    averageLength: valid.length > 0 ? totalLength / valid.length : 0,
    minLength,
    maxLength,
    items: transformed,
  };

  return report;
}

export interface TransformedItem { original: string; upper: string; reversed: string; length: number; }
export interface Report { totalItems: number; validCount: number; invalidCount: number; averageLength: number; minLength: number; maxLength: number; items: TransformedItem[]; }

