function transformItems(items: string[]): TransformedItem[] {
  return items.map(item => ({
    original: item,
    upper: item.toUpperCase(),
    reversed: item.split('').reverse().join(''),
    length: item.length,
  }));
}

function computeStats(transformed: TransformedItem[]): Pick<Report, 'averageLength' | 'minLength' | 'maxLength'> {
  if (transformed.length === 0) return { averageLength: 0, minLength: 0, maxLength: 0 };
  let totalLength = 0, minLength = Infinity, maxLength = 0;
  for (const t of transformed) {
    totalLength += t.length;
    if (t.length < minLength) minLength = t.length;
    if (t.length > maxLength) maxLength = t.length;
  }
  return { averageLength: totalLength / transformed.length, minLength, maxLength };
}

function buildReport(items: string[], valid: string[], invalid: string[], transformed: TransformedItem[], stats: Pick<Report, 'averageLength' | 'minLength' | 'maxLength'>): Report {
  return { totalItems: items.length, validCount: valid.length, invalidCount: invalid.length, ...stats, items: transformed };
}

